style.css:
@-moz-document domain("web.telegram.org") {
/* ChatGPT Hacker Green v1.5 palette and wallpaper */
html {
  background-color: #0a0a0a !important;
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
  color-scheme: dark !important;
}

/* The escaped first hyphen on Telegram theme tokens is for older CSS parsers. */

/* Web A theme tokens, including native dark mode and custom themes. */
html, html body, html body.theme-dark, #root, #Main {
  \2d -font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  \2d -font-family-monospace: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  \2d -font-family-rounded: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  \2d -color-background: rgba(1,22,10,.75) !important;
  \2d -color-background-secondary: rgba(2,26,12,.82) !important;
  \2d -color-background-secondary-accent: rgba(4,43,20,.95) !important;
  \2d -color-background-sidebar: rgba(1,22,10,.75) !important;
  \2d -color-background-selected: rgba(8,73,34,.95) !important;
  \2d -color-background-own: rgba(4,54,27,.58) !important;
  \2d -color-background-own-selected: rgba(8,73,34,.95) !important;
  \2d -color-background-compact-menu: rgba(2,23,11,.97) !important;
  \2d -color-background-compact-menu-reactions: rgba(2,23,11,.97) !important;
  \2d -color-background-compact-menu-hover: rgba(16,104,45,.47) !important;
  \2d -color-background-menu-separator: rgba(32,243,107,.18) !important;
  \2d -color-text: #d9ffe6 !important;
  \2d -color-text-rgb: 217,255,230 !important;
  \2d -color-text-own: #d9ffe6 !important;
  \2d -color-text-secondary: #9ee5b6 !important;
  \2d -color-text-secondary-rgb: 158,229,182 !important;
  \2d -color-text-secondary-own: #9ee5b6 !important;
  \2d -color-text-lighter: #9ee5b6 !important;
  \2d -color-text-meta: #70b68b !important;
  \2d -color-text-meta-rgb: 112,182,139 !important;
  \2d -color-text-meta-colored: #7fffac !important;
  \2d -color-message-meta-own: #7fffac !important;
  \2d -color-icon-secondary: #7fffac !important;
  \2d -color-placeholders: #70b68b !important;
  \2d -color-links: #7fffac !important;
  \2d -color-own-links: #7fffac !important;
  \2d -color-primary: #00ff66 !important;
  \2d -color-primary-foreground: #001b09 !important;
  \2d -color-primary-shade: #00e85c !important;
  \2d -color-primary-shade-darker: #00c84c !important;
  \2d -color-primary-shade-rgb: 0,232,92 !important;
  \2d -color-primary-opacity: rgba(0,255,102,.20) !important;
  \2d -color-primary-opacity-hover: rgba(0,255,102,.25) !important;
  \2d -color-primary-tint: rgba(0,255,102,.10) !important;
  \2d -color-accent-own: #7fffac !important;
  \2d -color-accent-own-rgb: 127,255,172 !important;
  \2d -color-borders: rgba(32,243,107,.18) !important;
  \2d -color-borders-input: rgba(28,240,102,.36) !important;
  \2d -color-borders-alternate: rgba(32,243,107,.18) !important;
  \2d -color-dividers: rgba(32,243,107,.18) !important;
  \2d -color-dividers-android: rgba(32,243,107,.18) !important;
  \2d -color-chat-hover: rgba(16,104,45,.47) !important;
  \2d -color-chat-active: rgba(8,73,34,.95) !important;
  \2d -color-item-hover: rgba(16,104,45,.47) !important;
  \2d -color-item-active: rgba(8,73,34,.95) !important;
  \2d -color-composer-button: #7fffac !important;
  \2d -color-toast-background: rgba(2,23,11,.97) !important;
  \2d -color-code: #7fffac !important;
  \2d -color-code-own: #7fffac !important;
  \2d -color-code-bg: rgba(4,43,20,.95) !important;
  \2d -color-code-own-bg: rgba(4,43,20,.95) !important;
  \2d -color-message-reaction: rgba(1,22,10,.75) !important;
  \2d -color-message-reaction-own: rgba(4,43,20,.95) !important;
  \2d -color-message-reaction-hover: rgba(16,104,45,.47) !important;
  \2d -color-message-reaction-hover-own: rgba(16,104,45,.47) !important;
  \2d -message-incoming-background: rgba(1,22,10,.75) !important;
  \2d -message-outgoing-background: rgba(4,54,27,.58) !important;
  \2d -message-incoming-selected: rgba(8,73,34,.95) !important;
  \2d -message-outgoing-selected: rgba(8,73,34,.95) !important;
  \2d -message-service-background: rgba(2,23,11,.97) !important;
  \2d -message-service-text: #d9ffe6 !important;
  \2d -action-message-bg: rgba(1,22,10,.75) !important;
  \2d -color-scrollbar: rgba(28,240,102,.36) !important;
  \2d -color-scrollbar-code: rgba(67,255,134,.65) !important;
}

/* Web K theme tokens, including app-generated RGB companions. */
html, html body, #page-chats, #page-chats .chat {
  \2d -font-regular: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  \2d -font-monospace: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  \2d -font-rounded: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  \2d -surface-color: rgba(1,22,10,.75) !important;
  \2d -surface-color-rgb: 1,22,10 !important;
  \2d -background-color: rgba(2,26,12,.82) !important;
  \2d -background-color-rgb: 2,26,12 !important;
  \2d -body-background-color: transparent !important;
  \2d -body-background-color-rgb: 10,10,10 !important;
  \2d -primary-text-color: #d9ffe6 !important;
  \2d -primary-text-color-rgb: 217,255,230 !important;
  \2d -secondary-text-color: #9ee5b6 !important;
  \2d -secondary-text-color-rgb: 158,229,182 !important;
  \2d -light-secondary-text-color: rgba(32,243,107,.18) !important;
  \2d -light-filled-secondary-text-color: rgba(4,43,20,.95) !important;
  \2d -secondary-color: #9ee5b6 !important;
  \2d -primary-color: #00ff66 !important;
  \2d -primary-color-rgb: 0,255,102 !important;
  \2d -dark-primary-color: #00c84c !important;
  \2d -dark-primary-color-rgb: 0,200,76 !important;
  \2d -light-primary-color: rgba(0,255,102,.14) !important;
  \2d -light-filled-primary-color: rgba(8,73,34,.95) !important;
  \2d -link-color: #7fffac !important;
  \2d -border-color: rgba(32,243,107,.18) !important;
  \2d -input-search-background-color: rgba(3,38,21,.46) !important;
  \2d -message-background-color: rgba(1,22,10,.75) !important;
  \2d -message-out-background-color: rgba(4,54,27,.58) !important;
  \2d -message-out-background-color-rgb: 4,54,27 !important;
  \2d -message-out-primary-color: #7fffac !important;
  \2d -message-out-primary-color-rgb: 127,255,172 !important;
  \2d -light-message-out-primary-color: rgba(32,243,107,.18) !important;
  \2d -light-filled-message-out-primary-color: rgba(4,43,20,.95) !important;
  \2d -light-filled-message-background-color: rgba(4,43,20,.95) !important;
  \2d -light-filled-message-out-background-color: rgba(4,43,20,.95) !important;
  \2d -dark-message-background-color: rgba(8,73,34,.95) !important;
  \2d -dark-message-out-background-color: rgba(8,73,34,.95) !important;
  \2d -message-highlighting-color: rgba(1,22,10,.75) !important;
  \2d -message-highlighting-color-rgb: 1,22,10 !important;
  \2d -message-highlighting-alpha: .75 !important;
  \2d -scrollbar-color: rgba(28,240,102,.36) !important;
}

/* Clear only app canvas and conversation wallpaper layers. */
html body, #root, #Main, #MiddleColumn, #MiddleColumn .messages-layout,
#page-chats, #main-columns, #column-center, #column-center .chat,
#column-center .bubbles {
  background-color: transparent !important;
  color: #d9ffe6 !important;
}
div#Main > div:first-child,
body:not(.has-auth-pages) > div[aria-hidden="true"]:first-child,
#column-center .chat [class*="chatBackground_Layer"],
#column-center .chat [class*="chatBackground__Layer"],
#column-center .chat > .chat-background,
#column-center .bubbles > .bubbles-background,
#MiddleColumn > .chat-background {
  visibility: hidden !important;
}
html, body, button, input, textarea, select, pre, code,
[contenteditable="true"], .auth-form, .input-field-input {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
}
input, textarea, [contenteditable="true"] {
  caret-color: #00ff66 !important;
}
input::placeholder, textarea::placeholder {
  color: #70b68b !important;
}
::selection { background: rgba(0,255,102,.35) !important; color: #f5fff7 !important; }

/* Sidebar glass, headers and navigation rails */
#LeftColumn, #column-left {
  background-color: rgba(2,24,13,.43) !important;
  background-image: linear-gradient(145deg, rgba(13,92,47,.35) 0%, rgba(4,47,25,.28) 40%, rgba(1,19,11,.59) 100%) !important;
  border-inline-end-color: rgba(67,255,134,.65) !important;
  box-shadow: inset -1px 0 0 rgba(28,240,102,.36), 5px 0 24px rgba(0,225,88,.13) !important;
}
#LeftColumn .LeftMain, #column-left .sidebar-content,
#column-left #chatlist-container, #column-left #folders-container {
  background-color: transparent !important;
}
#RightColumn, #column-right {
  background-color: rgba(2,26,12,.82) !important;
  border-inline-start-color: rgba(67,255,134,.65) !important;
  box-shadow: inset 1px 0 0 rgba(28,240,102,.36), -5px 0 24px rgba(0,225,88,.13) !important;
}
#MiddleColumn .MiddleHeader, #LeftColumn .LeftHeader,
#RightColumn .RightHeader, .chat > .topbar,
.sidebar .sidebar-header, .sidebar-header .sidebar-header__title,
.chat .pinned-container, #MiddleColumn .pinned-message {
  background-color: rgba(1,20,9,.58) !important;
  border-color: rgba(32,243,107,.18) !important;
}
#MiddleColumn .MiddleHeader, .chat > .topbar {
  box-shadow: inset 0 -1px 0 rgba(28,240,102,.36), 0 2px 14px rgba(0,255,102,.14) !important;
  backdrop-filter: blur(11px) saturate(125%) !important;
}

/* Chat bubbles, composer, input and attachment panels */
#MiddleColumn .message-input-wrapper, #column-center .input-message-container {
  \2d -chat-input-background: rgba(3,38,21,.46) !important;
  background-color: rgba(3,38,21,.46) !important;
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36) !important;
}
#column-center .input-message-input, #editable-message-text,
#MiddleColumn .message-input-wrapper .input-scroller {
  background-color: transparent !important;
  color: #d9ffe6 !important;
}
#MiddleColumn .message-input-wrapper:focus-within,
#column-center .input-message-container:focus-within {
  box-shadow: inset 0 0 0 1px rgba(67,255,134,.65), 0 0 10px rgba(0,255,102,.14) !important;
}
#LeftColumn .SearchInput, #LeftColumn .input-group input,
#column-left .input-search, #column-right .input-search,
.auth-form input, body.has-auth-pages .input-field-input {
  background-color: rgba(3,38,21,.46) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #d9ffe6 !important;
}
#MiddleColumn .Message:not(.own) .message-content.has-solid-background {
  \2d -background-color: rgba(1,22,10,.75) !important;
}
#MiddleColumn .Message.own .message-content.has-solid-background {
  \2d -background-color: rgba(4,54,27,.58) !important;
}
#MiddleColumn .message-content.has-solid-background,
#column-center .bubble:not(.service):not(.is-date):not(.is-media) .bubble-content {
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}
#MiddleColumn .message-content.has-solid-background:hover,
#column-center .bubble:not(.service):not(.is-date):not(.is-media) .bubble-content:hover {
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36) !important;
}

/* Menus, emoji/sticker picker, tooltips and dialogs */
.Menu .bubble, .Menu > .menu-container, .Modal .modal-dialog,
.SymbolMenu > .bubble, .EmojiTooltip, .Popover .bubble, .Tooltip,
.btn-menu, .popup-container, .emoji-dropdown, .tooltip,
#LeftColumn .SearchInput .Menu .bubble {
  background-color: rgba(2,23,11,.97) !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18), 0 6px 22px rgba(0,0,0,.36), 0 0 14px rgba(0,255,102,.14) !important;
}
.Menu .bubble, .btn-menu, .emoji-dropdown, .SymbolMenu > .bubble {
  backdrop-filter: blur(16px) saturate(132%) !important;
}
.MenuItem:hover, .btn-menu-item:hover, .ListItem > .ListItem-button:hover,
.chatlist-chat:hover, .row.clickable:hover, .tabs-tab .menu-horizontal-div-item:hover {
  background-color: rgba(16,104,45,.47) !important;
  box-shadow: inset 0 0 0 1px rgba(67,255,134,.65), 0 0 10px rgba(0,255,102,.14) !important;
}
.Chat.selected .ListItem-button, .Chat.active .ListItem-button,
.chatlist-chat.active, .chatlist-chat.is-active, .chatlist-chat[aria-selected="true"] {
  background-color: rgba(8,73,34,.95) !important;
  box-shadow: inset 2px 0 0 #00ff66 !important;
}

/* Buttons, keyboard focus, auth logo and scrollbars */
button.Button.primary:not(.outline):not(.text):not(.translucent),
button.main-button.send, .btn-color-primary:not(.danger), #column-center .btn-send:not(.is-recording):not(.disabled),
.btn-corner {
  background-color: #00ed61 !important;
  color: #001b09 !important;
}
.Button:hover, .btn-icon:hover, .btn-primary:hover, .btn-send:hover,
.btn-corner:hover, .input-search:focus-within {
  box-shadow: inset 0 0 0 1px rgba(67,255,134,.65), 0 0 10px rgba(0,255,102,.14) !important;
}
button:focus-visible, a:focus-visible, input:focus-visible,
textarea:focus-visible, select:focus-visible, [role="button"]:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
a:hover { text-decoration: underline; }
#auth #logo, .auth-form #logo, .auth-form .qr-plane {
  filter: hue-rotate(265deg) saturate(1.35) drop-shadow(0 0 12px rgba(0,255,102,.55)) !important;
}
body.has-auth-pages svg use[href="#logo"] {
  color: #00ff66 !important;
  fill: currentColor !important;
  filter: drop-shadow(0 0 12px rgba(0,255,102,.55)) !important;
}
html, body, .custom-scroll, .custom-scroll-x, .scrollable, .scrollable-y, .scrollable-x,
#MiddleColumn .MessageList, #column-left .chatlist {
  scrollbar-color: rgba(28,240,102,.36) rgba(1,22,10,.75) !important;
}
::-webkit-scrollbar-track { background-color: rgba(1,22,10,.75) !important; }
::-webkit-scrollbar-thumb {
  background-color: rgba(28,240,102,.36) !important;
  border-radius: 8px !important;
}
::-webkit-scrollbar-thumb:hover { background-color: rgba(67,255,134,.65) !important; }

/* Web A: unread chat, folder and jump-to-latest counters. */
.NT-X2xr9.npoDLolY:not(.yf73Yld8),
.ChatBadge__badge.ChatBadge__unread:not(.ChatBadge__muted),
.Tab .badge.Tab__badge--active,
#FoldersSidebar .RbmAYSe4,
#FoldersSidebar .Folder__badgeActive,
#LeftColumn .igX4WDoL,
#MiddleColumn .pqD5-OJE,
#MiddleColumn .ScrollDownButton__unread-count {
  color: #000 !important;
}

/* Web K: unread chat, toolbar, back and jump-to-latest counters. */
#page-chats .dialog-subtitle-badge-unread,
#page-chats .dialog-subtitle-badge.avatar-badge.unread,
#page-chats .sidebar-tools-button-notifications,
#page-chats .back-unread-badge,
#page-chats .bubbles-go-down .badge-primary:not(.badge-gray) {
  color: #000 !important;
}


/* Web K: unread counts in the horizontal folder tabs beneath Search. */
#folders-tabs .menu-horizontal-div-item .badge-primary,
#folders-tabs .menu-horizontal-div-item.active .badge {
  color: #000 !important;
}
}
